```json
{
  "root_causes": [
    {
      "service": "ts-food-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT p, service_name, span_name, count(*) n, quantile_cont(duration,0.95)/1e6 p95_ms FROM (SELECT 'norm' p, * FROM normal_traces UNION ALL SELECT 'ab', * FROM abnormal_traces) WHERE service_name = 'ts-food-service' AND span_name IN ('FoodOrderRepository.save','FoodOrderRepository.findByOrderId','Transaction.commit','SELECT foodsearch.entity.FoodOrder') GROUP BY 1,2,3 ORDER BY 3,1", "claim": "Food-service DB-backed spans (save, findByOrderId, commit, SELECT) p95 rose from a few ms to 200–385 ms in abnormal."},
        {"kind": "trace", "sql": "SELECT p, service_name, span_name, count(*) n, quantile_cont(duration,0.95)/1e6 p95_ms FROM (SELECT 'norm' p, * FROM normal_traces UNION ALL SELECT 'ab', * FROM abnormal_traces) WHERE service_name = 'ts-food-service' AND span_name IN ('FoodController.createFoodOrder','FoodController.getAllFood') GROUP BY 1,2,3 ORDER BY 3,1", "claim": "Food createFoodOrder p95 rose ~9 ms to ~422 ms, while getAllFood, which has no DB write, stayed flat at ~23–28 ms."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-food-service",
      "to": "ts-preserve-service",
      "evidence": [
        {"kind": "trace", "sql": "SELECT p, service_name, span_name, count(*) n, quantile_cont(duration,0.95)/1e6 p95_ms FROM (SELECT 'norm' p, * FROM normal_traces UNION ALL SELECT 'ab', * FROM abnormal_traces) WHERE service_name = 'ts-preserve-service' AND span_name IN ('POST /api/v1/preserveservice/preserve','PreserveController.preserve') GROUP BY 1,2,3 ORDER BY 3,1", "claim": "Preserve's preserve endpoint p95 rose from ~135 ms to ~2325 ms while its own time stayed near baseline, so the added time was in its food call."}
      ]
    },
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {"kind": "trace", "sql": "SELECT p, service_name, span_name, count(*) n, quantile_cont(duration,0.95)/1e6 p95_ms FROM (SELECT 'norm' p, * FROM normal_traces UNION ALL SELECT 'ab', * FROM abnormal_traces) WHERE service_name = 'ts-ui-dashboard' AND span_name LIKE '%preserve%' GROUP BY 1,2,3 ORDER BY 3,1", "claim": "UI dashboard's preserve endpoint p95 rose from ~134 ms to ~1880 ms, the user-facing symptom of the slowdown."}
      ]
    }
  ]
}
```

